content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-006

=== 用户原始指令 (query.txt) ===
列一串群消息，点一下能进群看详情，能从日历读会议安排，紧急的标红色

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "列一串群消息，点一下能进群看详情，能从日历读会议安排，紧急的标红色",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hmos://chat/group/detail"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "notifications": {
        "alertLabel": {
          "type": "string",
          "description": "群消息聚合中的紧急状态短标签。",
          "sampleValue": "紧急"
        },
        "messages": [
          {
            "senderName": {
              "type": "string",
              "description": "第一条群消息的群名或发送来源。",
              "sampleValue": "设计群"
            },
            "title": {
              "type": "string",
              "description": "第一条群消息的短摘要。",
              "sampleValue": "合同需确认"
            },
            "statusText": {
              "type": "string",
              "description": "第一条群消息的状态短标记。",
              "sampleValue": "急"
            },
            "statusColor": {
              "type": "string",
              "description": "第一条群消息状态文字颜色，紧急消息使用告警红色。",
              "sampleValue": "#ffed6f21"
            }
          },
          {
            "senderName": {
              "type": "string",
              "description": "第二条群消息的群名或发送来源。",
              "sampleValue": "项目群"
            },
            "title": {
              "type": "string",
              "description": "第二条群消息的短摘要。",
              "sampleValue": "十点同步"
            },
            "statusText": {
              "type": "string",
              "description": "第二条群消息的状态短标记。",
              "sampleValue": "新"
            },
            "statusColor": {
              "type": "string",
              "description": "第二条群消息状态文字颜色，普通未读使用次级文字色。",
              "sampleValue": "#99000000"
            }
          }
        ]
      },
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历会议唯一标识符，可用于查看会议详情。",
              "sampleValue": "calendar_evt_1001"
            },
            "title": {
              "type": "string",
              "description": "下一场会议标题。",
              "sampleValue": "评审会"
            },
            "dtStart": {
              "type": "string",
              "description": "下一场会议的开始时间，今天内使用 HH:MM 展示。",
              "sampleValue": "10:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "下一场会议的结束时间，今天内使用 HH:MM 展示。",
              "sampleValue": "11:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/person_3_fill.svg",
      "description": "三人群组实心图标，适合表达群消息聚合入口；黑色 SVG，需放在浅色或中性材质表面上。"
    }
  ]
}

